            if 0 <= x < w and 0 <= y < h:
                self_territory_set.add((x, y))

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue
        d_to_target = md(nx, ny, tx, ty)
        d_from_opp = dist_to_opponent(nx, ny)

        bonus = 0
        if (nx, ny) in opp_cells:
